use std::path::PathBuf;

use thiserror::Error;

#[derive(Debug, Error)]
pub enum FsApiError {
    #[error("{0}")]
    InvalidRequest(String),

    #[error("path traversal detected: '{path}'")]
    PathTraversal { path: PathBuf },

    #[error("path not found: '{path}'")]
    PathNotFound { path: PathBuf },

    #[error("cannot read directory '{path}': {source}")]
    CannotReadDirectory {
        path: PathBuf,
        #[source]
        source: std::io::Error,
    },

    #[error("cannot read metadata for '{path}': {source}")]
    CannotReadMetadata {
        path: PathBuf,
        #[source]
        source: std::io::Error,
    },

    #[error("cannot move file from '{from}' to '{to}': {source}")]
    CannotMoveFile {
        from: PathBuf,
        to: PathBuf,
        #[source]
        source: std::io::Error,
    },

    #[error("cannot copy file from '{from}' to '{to}': {source}")]
    CannotCopyFile {
        from: PathBuf,
        to: PathBuf,
        #[source]
        source: std::io::Error,
    },

    #[error("cannot delete file '{path}': {source}")]
    CannotDeleteFile {
        path: PathBuf,
        #[source]
        source: std::io::Error,
    },

    #[error("cannot delete directory '{path}': {source}")]
    CannotDeleteDirectory {
        path: PathBuf,
        #[source]
        source: std::io::Error,
    },

    #[error("I/O error: {0}")]
    IoError(#[from] std::io::Error),
}

use std::path::PathBuf;

use serde::{Deserialize, Serialize};

/// Request to list directory contents with bounded output.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ListDirRequest {
    /// Root directory to list.
    pub path: PathBuf,

    /// Maximum depth to recurse. None means list only the directory itself.
    pub depth_limit: Option<usize>,

    /// Maximum number of entries to return before truncating.
    pub entry_limit: Option<usize>,

    /// Glob patterns to include (e.g., "*.rs"). If empty, include all.
    pub include_globs: Vec<String>,

    /// Glob patterns to exclude (e.g., "target/**", ".git/**").
    pub exclude_globs: Vec<String>,

    /// Whether to honor .gitignore and other standard filters.
    pub honor_ignore: bool,
}

/// Request to get file/directory metadata.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct StatRequest {
    /// Path to the file or directory.
    pub path: PathBuf,
}

/// Request to move a file or directory.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct MoveFileRequest {
    /// Source path.
    pub from: PathBuf,

    /// Destination path.
    pub to: PathBuf,

    /// Whether to overwrite existing destination.
    pub overwrite: bool,
}

/// Request to rename a file or directory (in-place).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct RenameFileRequest {
    /// Current path.
    pub from: PathBuf,

    /// New name (relative to parent directory).
    pub to: PathBuf,
}

/// Request to copy a file.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct CopyFileRequest {
    /// Source path.
    pub from: PathBuf,

    /// Destination path.
    pub to: PathBuf,

    /// Whether to overwrite existing destination.
    pub overwrite: bool,
}

/// Request to delete a file.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct DeleteFileRequest {
    /// Path to the file to delete.
    pub path: PathBuf,
}

/// Request to delete a directory (recursively).
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct DeleteDirRequest {
    /// Path to the directory to delete.
    pub path: PathBuf,

    /// Whether to allow deleting non-empty directories.
    pub recursive: bool,
}

use std::path::PathBuf;

use serde::{Deserialize, Serialize};

/// Conflict kind for mutation operations.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ConflictKind {
    DestinationExists,
    SourceMissing,
    PermissionDenied,
    Other(String),
}

/// Conflict encountered during a mutation operation.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Conflict {
    pub kind: ConflictKind,
    pub path: PathBuf,
    pub message: String,
}

/// Entry kind.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum EntryKind {
    File,
    Directory,
    Symlink,
}

/// A directory entry.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct DirEntry {
    /// Relative path from the requested root.
    pub path: PathBuf,
    pub kind: EntryKind,
    pub size: Option<u64>,
}

/// Result of a list_dir operation.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ListDirResult {
    pub entries: Vec<DirEntry>,
    /// Whether results were truncated due to entry limit.
    pub truncated: bool,
    /// Total entries found (if available), even beyond the limit.
    pub total_found: Option<usize>,
}

/// Metadata result for a single path.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct StatResult {
    pub exists: bool,
    pub kind: Option<EntryKind>,
    pub size: Option<u64>,
    /// Modified time as Unix epoch seconds.
    pub modified_secs: Option<u64>,
}

/// Result of a mutation operation.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct MutationResult {
    /// Paths affected by the operation.
    pub affected_paths: Vec<PathBuf>,
    /// Conflicts encountered.
    pub conflicts: Vec<Conflict>,
}

//! Bounded filesystem operations API.
//!
//! Provides core logic for listing directories, reading metadata, and performing
//! conflict-aware file mutations. This API is transport-agnostic and designed to
//! be used by CLI, MCP, and HTTP adapters.
//!
//! # Security
//!
//! - Path traversal protection: all operations reject or canonicalize paths that
//!   escape the provided root.
//! - Bounded operations: depth and entry limits prevent memory exhaustion on large
//!   or malicious directory trees.
//! - No symlink following outside the root by default.
//!
//! # Entry points
//!
//! - [`list_dir()`]: List directory contents with bounded output.
//! - [`stat()`]: Get file/directory metadata without reading content.
//! - [`move_file()`], [`rename_file()`], [`copy_file()`], [`delete_file()`],
//!   [`delete_dir()`]: Conflict-aware mutation operations.

pub mod error;
pub mod list_dir;
pub mod mutation;
pub mod request;
pub mod response;
pub mod stat;

pub use error::FsApiError;
pub use list_dir::list_dir;
pub use mutation::{copy_file, delete_dir, delete_file, move_file, rename_file};
pub use request::{
    CopyFileRequest, DeleteDirRequest, DeleteFileRequest, ListDirRequest, MoveFileRequest,
    RenameFileRequest, StatRequest,
};
pub use response::{
    Conflict, ConflictKind, DirEntry, EntryKind, ListDirResult, MutationResult, StatResult,
};
pub use stat::stat;

//! fs — bounded filesystem operations utility
//!
//! Provides safe directory listing and conflict-aware file mutations with bounded output.
//!
//! ## Usage
//!
//! ```text
//! # List directory with depth and entry limits
//! fs list-dir /path/to/dir --depth 2 --limit 100
//!
//! # List with glob patterns
//! fs list-dir . --include "*.rs" --exclude "target/**"
//!
//! # Get file/directory metadata
//! fs stat /path/to/file
//!
//! # Move file (conflict detection)
//! fs move /src /dst
//! fs move /src /dst --overwrite
//!
//! # Rename file (in-place)
//! fs rename /old/path /new/name
//!
//! # Copy file
//! fs copy /src /dst
//! fs copy /src /dst --overwrite
//!
//! # Delete operations
//! fs delete-file /path/to/file
//! fs delete-dir /path/to/dir --recursive
//!
//! # Output formats
//! fs list-dir . --json
//! fs list-dir . --toon
//! ```

use std::path::PathBuf;

use clap::{Parser, Subcommand};
use fs_api::{
    CopyFileRequest, DeleteDirRequest, DeleteFileRequest, FsApiError, ListDirRequest,
    MoveFileRequest, RenameFileRequest, StatRequest, copy_file, delete_dir, delete_file, list_dir,
    move_file, rename_file, stat,
};

/// fs — bounded filesystem operations.
///
/// Safe directory listing and conflict-aware file mutations with bounded output.
#[derive(Debug, Parser)]
#[command(name = "fs", version, about)]
struct Args {
    #[command(subcommand)]
    command: Command,

    /// Output as JSON.
    #[arg(long, global = true, conflicts_with = "toon")]
    json: bool,

    /// Output as TOON (compact machine-readable format).
    #[arg(long, global = true)]
    toon: bool,
}

#[derive(Debug, Subcommand)]
enum Command {
    /// List directory contents with bounded output.
    ///
    /// Supports depth limits, entry limits, glob patterns, and .gitignore honor.
    ListDir {
        /// Directory path to list.
        path: PathBuf,

        /// Maximum depth to recurse. Omit to list only the directory itself.
        #[arg(long)]
        depth: Option<usize>,

        /// Maximum number of entries to return before truncating.
        #[arg(long)]
        limit: Option<usize>,

        /// Glob patterns to include (e.g., "*.rs"). Can be specified multiple times.
        #[arg(long)]
        include: Vec<String>,

        /// Glob patterns to exclude (e.g., "target/**", ".git/**"). Can be specified multiple times.
        #[arg(long)]
        exclude: Vec<String>,

        /// Honor .gitignore and other standard filters.
        #[arg(long)]
        honor_ignore: bool,
    },

    /// Get file/directory metadata without reading content.
    Stat {
        /// Path to the file or directory.
        path: PathBuf,
    },

    /// Move a file or directory.
    ///
    /// Conflict detection: reports DestinationExists unless --overwrite is set.
    Move {
        /// Source path.
        from: PathBuf,

        /// Destination path.
        to: PathBuf,

        /// Overwrite existing destination.
        #[arg(long)]
        overwrite: bool,
    },

    /// Rename a file or directory (in-place).
    Rename {
        /// Current path.
        from: PathBuf,

        /// New name (relative to parent directory).
        to: PathBuf,
    },

    /// Copy a file.
    Copy {
        /// Source path.
        from: PathBuf,

        /// Destination path.
        to: PathBuf,

        /// Overwrite existing destination.
        #[arg(long)]
        overwrite: bool,
    },

    /// Delete a file.
    DeleteFile {
        /// Path to the file to delete.
        path: PathBuf,
    },

    /// Delete a directory (optionally recursive).
    DeleteDir {
        /// Path to the directory to delete.
        path: PathBuf,

        /// Allow deleting non-empty directories.
        #[arg(long)]
        recursive: bool,
    },
}

fn main() -> Result<(), FsApiError> {
    let args = Args::parse();

    let output_format = if args.json {
        OutputFormat::Json
    } else if args.toon {
        OutputFormat::Toon
    } else {
        OutputFormat::Json // default
    };

    match args.command {
        Command::ListDir {
            path,
            depth,
            limit,
            include,
            exclude,
            honor_ignore,
        } => {
            let request = ListDirRequest {
                path,
                depth_limit: depth,
                entry_limit: limit,
                include_globs: include,
                exclude_globs: exclude,
                honor_ignore,
            };

            let result = list_dir(&request)?;
            print_output(&result, output_format)?;
        }

        Command::Stat { path } => {
            let request = StatRequest { path };
            let result = stat(&request)?;
            print_output(&result, output_format)?;
        }

        Command::Move { from, to, overwrite } => {
            let request = MoveFileRequest { from, to, overwrite };
            let result = move_file(&request)?;
            print_output(&result, output_format)?;
        }

        Command::Rename { from, to } => {
            let request = RenameFileRequest { from, to };
            let result = rename_file(&request)?;
            print_output(&result, output_format)?;
        }

        Command::Copy { from, to, overwrite } => {
            let request = CopyFileRequest { from, to, overwrite };
            let result = copy_file(&request)?;
            print_output(&result, output_format)?;
        }

        Command::DeleteFile { path } => {
            let request = DeleteFileRequest { path };
            let result = delete_file(&request)?;
            print_output(&result, output_format)?;
        }

        Command::DeleteDir { path, recursive } => {
            let request = DeleteDirRequest { path, recursive };
            let result = delete_dir(&request)?;
            print_output(&result, output_format)?;
        }
    }

    Ok(())
}

#[derive(Debug, Clone, Copy)]
enum OutputFormat {
    Json,
    Toon,
}

fn print_output<T: serde::Serialize>(
    value: &T,
    format: OutputFormat,
) -> Result<(), FsApiError> {
    match format {
        OutputFormat::Json => {
            let json = serde_json::to_string_pretty(value).map_err(|e| {
                FsApiError::InvalidRequest(format!("serialization error: {}", e))
            })?;
            println!("{}", json);
        }
        OutputFormat::Toon => {
            let toon = toon_format::encode_default(value).map_err(|e| {
                FsApiError::InvalidRequest(format!("TOON encoding error: {}", e))
            })?;
            println!("{}", toon);
        }
    }
    Ok(())
}

